function fewestPeople(answers: number[]): number {
  const count = new Map<number, number>();
  for (const a of answers) count.set(a, (count.get(a) ?? 0) + 1);
  let total = 0;
  for (const [x, c] of count) {
    const g = x + 1;
    total += Math.ceil(c / g) * g;
  }
  return total;
}

