function fewestPeople(answers: number[]): number {
  const open = new Map<number, number>();
  let total = 0;
  for (const x of answers) {
    const left = open.get(x) ?? 0;
    if (left > 0) {
      open.set(x, left - 1); // join an existing group
    } else {
      total += x + 1; // start a new group of x + 1 people
      open.set(x, x);
    }
  }
  return total;
}

